#include <stdio.h>
#define KMH_TO_MS (1000.0 / 3600.0)
#define KM_PER_MILE 1.609344
int main(void) {
    double kmh;
    printf("Enter speed in km/h: ");
    scanf("%lf", &kmh);
    printf("%.2lf km/h = %.2lf m/s = %.2lf mph\n", kmh, kmh * KMH_TO_MS, kmh / KM_PER_MILE);
    return 0;
}

#include <stdio.h>
#define BASIC_CHARGE 6.50
#define TIER1_LIMIT 600
#define TIER1_RATE 0.10
#define TIER2_RATE 0.15
int main(void) {
    int kwh;
    double bill;
    printf("Enter energy used (kWh): ");
    scanf("%d", &kwh);
    if (kwh < 0) {
        printf("Error: energy cannot be negative.\n");
    } else {
        if (kwh <= TIER1_LIMIT)
            bill = BASIC_CHARGE + kwh * TIER1_RATE;
        else
            bill = BASIC_CHARGE + TIER1_LIMIT * TIER1_RATE + (kwh - TIER1_LIMIT) * TIER2_RATE;
        printf("Total bill: $%.2lf\n", bill);
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int n, i, sum = 0;
    printf("Enter a positive integer: ");
    scanf("%d", &n);
    i = 1;
    while (i <= n) {
        sum += i;
        i += 2;
    }
    printf("Sum of odd numbers from 1 to %d: %d\n", n, sum);
    return 0;
}
